// Live radio stations (generated by scripts/convert-radio.mjs).
import fs from "node:fs/promises";
import path from "node:path";
import { cache } from "react";

export type RadioCategory = "recitations" | "tafsir" | "hadith" | "athkar" | "translations";

export type RadioStation = {
  id: number;
  url: string;
  slug: string;
  category: RadioCategory;
  name: string;
  nameEn: string;
};

export const getRadioStations = cache(async (): Promise<RadioStation[]> =>
  JSON.parse(await fs.readFile(path.join(process.cwd(), "data/radio/stations.json"), "utf8")),
);
